public static int process(StringBuffer sb){
  int count = 0;
  for (int i=0; i<sb.length(); ++i)
    if (sb.charAt(i) > 'a' + count) {
      sb.setCharAt(i,
                   (char)(sb.charAt(i)+1));
      ++count;
    }
  return count;
}

