                (Comparable[] A) {
    MergeSort(A, 0, A.length);
  }
  private static void MergeSort
      (Comparable[] A, int front,
                         int back) {
    int mid=(front+back)/2;
    if (mid==front) return;
    MergeSort(A,front,mid);
    MergeSort(A,mid,back);
    Merge(A,front,back);
  }

