    if (mid==front) return;
    MergeSort(A,front,mid);
    MergeSort(A,mid,back);
    Merge(A,front,back);
  }
  private static void Merge(Comparable[] A,
                     int front, int back) {
    Comparable[] temp =
           new Comparable[back-front];
    int i=front, j=(front+back)/2, k=0;
    int mid=j;

    while(i<mid && j<back) {
      if (A[i].compareTo(A[j])<0)
        temp[k++]=A[i++];
      else
        temp[k++]=A[j++];
    }

    while (i<mid) temp[k++]=A[i++];
    while (j<back) temp[k++]=A[j++];
    for(i=0; i<back-front; ++i)
      A[front+i]=temp[i];
  }
}

